// ReportService.java
byte[] buildMonthly(YearMonth month) {
    var orders   = CompletableFuture.supplyAsync(() -> ordersSection(month),   reportExecutor);
    var payments = CompletableFuture.supplyAsync(() -> paymentsSection(month), reportExecutor);
    var refunds  = CompletableFuture.supplyAsync(() -> refundsSection(month),  reportExecutor);
    return pdf.render(orders.join(), payments.join(), refunds.join());   // dòng 58
}

// ExecutorConfig.java
@Bean ExecutorService reportExecutor() {
    return Executors.newFixedThreadPool(8, Thread.ofPlatform().name("report-worker-", 1).factory());
}

